<template>
  <div class="terminal-container">
    <div class="prompt">
        <h2 :style="{ color: colors.green }">$</h2>
        <h2 :style="{ color: colors.yellow }"> ls -la</h2>
        <h2 :style="{color:colors.text}">work_experience/</h2>
  </div>

    
    <WorkHistory
      :experiences="experiences.projects"
      :selected-id="selectedExperienceId"
      @select-experience="selectExperience"
    />

    <Transition name="slide">
      <div v-if="selectedExperience" class="detail-panel">
        <ExperienceCard 
          :experience="selectedExperience"
          @close="selectedExperienceId = null" 
        />
      </div>
    </Transition>
    
    <div class="status-messages">
      <div class="success">[SUCCESS] experience data loaded successfully</div>
      <div class="info">[INFO] Showing {{selectedExperienceId}} of {{totalId}} positions</div>
    </div>
  </div>
</template>

<script setup>
import { ref, computed } from 'vue';
import WorkHistory from '@/components/organisms/WorkHistory.vue';
import ExperienceCard from '@/components/molecules/ExperienceCard.vue';
import {colors} from '@/styles/archPalette.js'

// Importa otros componentes atómicos (FileItem, BaseTag) si es necesario usarlos aquí

const experiences = defineProps({
  projects: Array, 
});

const totalId = experiences.projects.length;
const selectedExperienceId = ref(1); // Muestra la primera por defecto

const selectedExperience = computed(() => {
  return experiences.projects?.find(exp => exp.id === selectedExperienceId.value) || null;
});

const selectExperience = (id) => {
  selectedExperienceId.value = id;
};
</script>

<style scoped>
/* Estilos Globales y de Contenedor */
.terminal-container {
  background-color: var(colors.bg);
  color: #d4d4d4;
  font-family: 'Consolas', monospace;
  padding: 20px;
  position: relative; /* Necesario para el detalle absoluto */
  min-height: 800px;
}

.prompt {
  color: #99cc99; /* Verde claro */
  margin-bottom: 20px;
  display:flex;
  gap: 0.75rem;
}

/* Estilos para el Despliegue Lateral (TRANSITION) */
.detail-panel {
  position: absolute;
  top: 0;
  right: 0;
  width: 70%; /* Ajusta el ancho según lo que necesites */
  height: 100%;
  background-color: #2e2e2e; /* Color de fondo más oscuro para el detalle */
  box-shadow: -5px 0 15px rgba(0, 0, 0, 0.5);
  padding: 20px;
  z-index: 10;
}

/* Clases de transición de Vue */
.slide-enter-active,
.slide-leave-active {
  transition: transform 0.3s ease-in-out;
}

.slide-enter-from,
.slide-leave-to {
  transform: translateX(100%); /* Comienza y termina fuera del contenedor */
}

/* Mensajes de Estado */
.status-messages {
  margin-top: 20px;
  font-size: 0.8em;
}
.success { color: #99cc99; }
.info { color: #5c7e91; }
</style>